return "\n#充值 (28***)\n#充值前校验\ncheck_recharge 28001 {\n    request {\n        id 0 : integer\n        client 1 : integer\n    }\n    response {\n        result 0 : integer # 7 需要先购买前置礼包\n        products 1 : *product\n    }\n}\n\n#获取充值掉落预览\nget_recharge_items_drop 28002 {\n    request {\n        id 0 : integer\n    }\n    response {\n        result 0 : integer\n        gold 1 : integer\n        diamond 2 : integer\n        sp 3 : integer\n        dropitem 4 : *dropids\n    }\n}\n\n#充值界面通过钻石购买\nrecharge_from_diamond 28003 {\n    request {\n        id 0 : integer\n    }\n    response {\n        result 0 : integer\n        cost_items 1 : *consumeids\n        items 2 : *item\n        diamond 3 : integer\n        gold 4 : integer\n        sp 5 : integer\n        cost_diamond 6 : integer\n    }\n}\n\n# 累充奖励\nget_totalrecharge_award 28004 {\n    request {\n        id 0 : integer\n    }\n    response {\n        result 0 : integer\n        items 1 : *item\n        diamond 2 : integer\n        gold 3 : integer\n        sp 4 : integer\n    }\n}\n\n# 免费礼包\nget_free_award 28005 {\n    request {\n        id 0 : integer\n    }\n    response {\n        result 0 : integer\n        items 1 : *item\n        diamond 2 : integer\n        gold 3 : integer\n        sp 4 : integer\n    }\n}\n\n#充值界面通过礼品卡购买\nrecharge_from_card 28006 {\n    request {\n        id 0 : integer\n    }\n    response {\n        result 0 : integer\n        cost_items 1 : *consumeids\n        items 2 : *item\n        diamond 3 : integer\n        gold 4 : integer\n        sp 5 : integer\n        cost_diamond 6 : integer\n    }\n}\n\n#去掉充值的红点\ndelete_recharge_new_tag 28007 {\n    request {\n        group 0 : integer\n    }\n}\n\n#领取新手回流月卡的奖励\nget_other_monthcard_reward 28008 {\n    request {\n        rechargeid 0 : integer\n    }\n    response {\n        result 0 : integer #1 成功 2 已领取 3 已过期 4 参数错误\n        items 1 : *item\n        diamond 2 : integer\n        gold 3 : integer\n        sp 4 : integer\n        lastreward 5 : boolean\n    }\n}\n\n#获取累计充值信息\nget_recharge_money 28009 {\n\n    response {\n        result 0 : integer #1 成功 \n        daily 1 : integer #当日\n    }\n}\n\n#领取回归礼包累登奖励\nget_returnback_recharge_loin_reward 28010 {\n    request {\n        rechargeid 0 : integer\n    }\n    response {\n        result 0 : integer #1 成功 2 已领取\n        items 1 : *item\n        diamond 2 : integer\n        gold 3 : integer\n    }\n}\n\n#领取活跃礼包每日奖励\nget_active_gift_daily_reward 28011 {\n    request {\n        rechargeid 0 : integer\n    }\n    response {\n        result 0 : integer #1 成功 2 已领取\n        items 1 : *item\n        diamond 2 : integer\n        gold 3 : integer\n    }\n}\n\n#获取订阅链接\nget_subscribe_url 28012 {\n    request {\n        product 0 : integer #产品id\n        channel 1 : string #渠道\n    }\n    response {\n        result 0 : integer  # 1 成功 2 网络错误,请重试 3 该产品暂时不支持购买 4 产品订阅中 5 当前无法购买订阅产品\n        url 1 : string\n        productid 2: string\n        uuid 3 : string #苹果account token\n    }\n}\n\n#苹果购买成功 提交收据\napple_pay_success 28013 {\n    request {\n        playerid 0 : string\n        productid 1 : string\n        token 2 : string\n        receipt_type 3 : string # receipt_type: subscribe, recharge\n    }\n    response {\n        result 0 : integer #1 成功 2 网络错误,请重试 3 产品不存在 8 token校验错误\n    }\n}\n\n#苹果充值请求\napple_recharge_request 28014 {\n    request {\n        product 0 : integer #产品id\n    }\n    response {\n        result 0 : integer  # 1 成功 2 网络错误,请重试 3 该产品暂时不支持购买\n        uuid 1 : string #苹果account token\n        productid 2: string #产品id\n    }\n}\n\n#条件触发礼包触发条件\ncondition_packs_trigger 28015 {\n    request {\n        shop_type 0 : integer # 礼包类型\n    }\n    response {\n        result 0 : integer  # 1 未购买该类型礼包的付费礼包，客户端继续弹窗 2 触发礼包类型出错 3 重置礼包次数成功 4 不需要重置购买次数\n    }\n}\n\n#获取活跃的条件触发礼包\nget_condition_packs_active 28016 {\n    response {\n        result 0 : integer  # 1 成功\n        packs_types 1 : *integer    # 目前活跃的礼包\n    }\n}\n\n#获取一些特殊处理过的礼包的信息\nget_special_packs_info 28017 {\n    response {\n        .result_info {\n            shoptype    0 : integer\n            id          1 : integer\n            starttime   2 : integer\n            endtime     3 : integer\n        }\n        result      0 : integer  # 1 成功\n        result_info 1 : *result_info    # 礼包信息\n    }\n}\n"
